export const ep04gSpan = (sceneId: string, key: string): Ep04GWindow => {
  const s = EP04G_SPANS[sceneId]?.[key];
  if (!s) return { from: 0, to: 1, frames: 1 };
  return s;
};

export const ep04gRms = (sceneId: string, file: string, localFrame: number): number => {
  const w = EP04G_SPANS[sceneId]?.[file];
  if (!w || localFrame < w.from || localFrame >= w.to) return 0;
  const env = EP04G_RMS[file];
  if (!env) return 0;
  return env[Math.min(env.length - 1, Math.max(0, Math.floor(localFrame - w.from)))] ?? 0;
};

export const ep04gSpeakRms = (sceneId: string, files: readonly string[], localFrame: number): number => {
  let m = 0;
  for (const f of files) {
    const v = ep04gRms(sceneId, f, localFrame);
    if (v > m) m = v;
  }
  return m;
};
